document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function e(n){return`${n.toFixed(1)}%`}function i(n,e,i,t="info"){return`\n      <div class="insight-card ${t}">\n        <h6>${n}</h6>\n        <div class="metric-value">${e}</div>\n        <div class="metric-subtitle">${i}</div>\n      </div>\n    `}const t=document.getElementById("dental-practice-form"),a=document.getElementById("dental-practice-result");t&&t.addEventListener("submit",function(t){t.preventDefault();const s=parseInt(document.getElementById("dental-chairs").value),r=parseFloat(document.getElementById("equipment-cost").value),o=parseFloat(document.getElementById("renovation-cost").value),l=parseFloat(document.getElementById("working-capital").value),d=parseInt(document.getElementById("patients-per-day").value),c=parseFloat(document.getElementById("avg-visit-cost").value),p=parseInt(document.getElementById("working-days").value),v=parseFloat(document.getElementById("chair-utilization").value),u=parseFloat(document.getElementById("staff-salaries").value),g=parseFloat(document.getElementById("materials-cost").value),m=parseFloat(document.getElementById("rent").value),h=parseFloat(document.getElementById("other-expenses").value);if(s<=0||d<=0||c<=0)return a.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const f=r+o+l,y=d*(v/100),w=12*(s*y*c*p),$=.15*w,b=w+$,k=u+g+m+h,I=12*k,E=b-I,P=E/12,B=E/b*100,F=f/E,x=E/f*100,D=b/s,M=s*y*p,C=b/12/M;let L="info";E<0?L="warning":B>50&&(L="success");let A="info";x<25?A="warning":x>50&&(A="success");let O="info";v<60?O="warning":v>80&&(O="success"),a.innerHTML=`\n        <div class="business-plan-results">\n          <h3>🦷 Dental Practice Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n            ${i("💰 Total Investment",n(f),"Initial capital required","info")}\n            ${i("📈 Monthly Profit",n(P),`Margin: ${e(B)}`,L)}\n            ${i("⏱️ Payback Period",`${F.toFixed(1)} years`,`ROI: ${e(x)}`,F<=3?"success":"warning")}\n            ${i("🪑 Chair Utilization",e(v),"Efficiency rate",O)}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Dental equipment</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Facility buildout</span>\n                  <span>${n(o)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Licenses & working capital</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n(f)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Annual Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Core services (${Math.round(12*M)} patients/year)</span>\n                  <span>${n(w)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Specialty procedures (implants, orthodontics)</span>\n                  <span>${n($)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Annual Revenue</strong></span>\n                  <span><strong>${n(b)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Staff salaries (dentists & hygienists)</span>\n                  <span>${n(u)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Dental materials & lab costs</span>\n                  <span>${n(g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Facility rent</span>\n                  <span>${n(m)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Other expenses</span>\n                  <span>${n(h)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Expenses</strong></span>\n                  <span><strong>${n(k)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>🏥 Operational Metrics</h6>\n              <div class="metric-subtitle">\n                Dental chairs: <strong>${s} units</strong><br>\n                Patients/day: <strong>${Math.round(y)} per chair</strong><br>\n                Average visit fee: <strong>${n(c)}</strong>\n              </div>\n            </div>\n            <div class="insight-card ${E>0?"success":"warning"}">\n              <h6>💰 Practice Efficiency</h6>\n              <div class="metric-subtitle">\n                Revenue per chair: <strong>${n(D)}/year</strong><br>\n                Patients/month: <strong>${Math.round(M)}</strong><br>\n                Revenue per patient: <strong>${n(C)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${P>0?"success":"warning"}">\n              <h6>📈 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(E)}</strong><br>\n                Weekly profit: <strong>${n(E/52)}</strong><br>\n                Daily profit: <strong>${n(E/(12*p))}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>🎯 Growth Potential</h6>\n              <div class="metric-subtitle">\n                Working days: <strong>${p}/month</strong><br>\n                Expansion potential: <strong>+${s} chairs</strong><br>\n                Utilization reserve: <strong>${e(100-v)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${B<40?"<li>⚠️ Low profitability. Consider increasing fees or reducing operating costs.</li>":""}\n              ${v<70?"<li>📅 Low chair utilization. Improve scheduling efficiency and patient flow.</li>":""}\n              ${F>4?"<li>⏰ Long payback period. Optimize startup costs or increase patient volume.</li>":""}\n              ${c<60?"<li>💰 Low average visit fee. Expand high-value specialty services.</li>":""}\n              ${B>60?"<li>🎉 Excellent profitability! Consider expanding operatory capacity.</li>":""}\n              <li>🦷 Add specialty services: implants, orthodontics, cosmetic dentistry for higher margins.</li>\n              <li>📱 Implement online scheduling and patient communication systems.</li>\n              <li>🤝 Contract with insurance providers for steady patient flow.</li>\n              <li>⭐ Develop patient loyalty programs and referral incentives.</li>\n              <li>📊 Track detailed analytics on procedure profitability and patient retention.</li>\n              <li>🎓 Invest in continuing education and advanced training for staff.</li>\n              <li>🔄 Optimize scheduling for maximum chair utilization and efficiency.</li>\n              <li>🌐 Build strong online presence and reputation management.</li>\n              <li>💳 Offer flexible payment plans and financing options.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.dentalPracticeBusinessData={"Number of Chairs":s,"Total Investment ($)":f,"Annual Revenue ($)":b,"Annual Expenses ($)":I,"Annual Profit ($)":E,"Monthly Profit ($)":P,"Profit Margin (%)":B,"Annual ROI (%)":x,"Payback Period (years)":F,"Patients per Day (per chair)":d,"Average Visit Fee ($)":c,"Chair Utilization (%)":v,"Revenue per Chair ($)":D}}),window.downloadCSV=function(){if(!window.dentalPracticeBusinessData)return;const n=Object.entries(window.dentalPracticeBusinessData).map(([n,e])=>`"${n}","${"number"==typeof e?e.toFixed(2):e}"`).join("\n"),e=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),i=document.createElement("a");i.href=URL.createObjectURL(e),i.download="dental-practice-business-plan.csv",i.click()}});